using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Windows.Forms;
namespace GearLab {
 public static class WorkspaceTests {
  public static int Run(string folder){Directory.CreateDirectory(folder);int checks=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks++;};Action<Func<bool>,string> wait=(ready,label)=>{var clock=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&clock.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(15);}check(ready(),label);};try{
   using(var reducers=new ReducerWorkspaceForm())using(var shell=new WorkspaceShell(reducers)){
    shell.Show();wait(()=>reducers.MainView!=null,"common reducer editor starts");var page=shell.Pages.SelectedTab;reducers.SelectWave();reducers.MainView.ShowFullModel();wait(()=>reducers.MainView.SceneReady,"wave shared 3D ready");check(reducers.MainView.CurrentParameters.Kind==4,"wave uses MainForm");var parameters=ReleaseSupport.Serialize(reducers.MainView.CurrentParameters);
    shell.Navigate("robot");var robot=(RobotDesignerForm)shell.Pages.SelectedTab.Tag;wait(()=>robot.Build!=null&&robot.Scene.Ready,"robot scene ready");check(robot.Build.Model.Valid,"default robot valid");check(!robot.TopLevel&&Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"one top level window");
    robot.SetStage(3);var joint=robot.Document.Joints[0];double previous=joint.Position;var tip=robot.Build.Current[robot.Document.Joints.Last().Id].Tip;int builds=robot.Scene.MeshBuildCount;robot.SetJointPose(joint.Id,Math.Min(joint.Maximum,previous+20));check(robot.Scene.MeshBuildCount==builds,"pose does not rebuild geometry");check((robot.Build.Current[robot.Document.Joints.Last().Id].Tip-tip).Length>.01,"pose moves actual tool");check(Math.Abs(robot.Analysis.Joints[0].Required-RobotSolver.Solve(robot.Build).Joints[0].Required)<1e-6,"pose updates loads");robot.SetJointPose(joint.Id,10000);check(joint.Position==joint.Maximum,"pose respects limits");robot.SetJointPose(joint.Id,previous);
    foreach(string key in new[]{"mechanism","settings","train","reducer","robot","reducer"}){shell.Navigate(key);Application.DoEvents();check(Application.OpenForms.Cast<Form>().Count(f=>f.TopLevel)==1,"one window: "+key);}
    check(ReferenceEquals(shell.Pages.SelectedTab,page),"return to same reducer tab");check(parameters==ReleaseSupport.Serialize(reducers.MainView.CurrentParameters),"parameters preserved across sections");check(shell.Pages.TabCount==5,"one tab per current section");shell.ApproveTestClose();shell.Close();
   }File.WriteAllText(Path.Combine(folder,"workspace-results.txt"),"PASS "+checks+" current-workspace assertions: five sections, shared wave, state preservation, joint pose/limits/loads.",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"workspace-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
